Rendben, most elkészítem a teljes production-ready ATS backend implementációt a Cerebras GPT-OSS 120B modellhez, 65000 token output limittel, minden szükséges fájllal.[1][2][3]

```ats
(***********************************************************************)
(* main.dats - Cerebras GPT-OSS 120B Backend - Teljes implementáció  *)
(***********************************************************************)

#include "share/atspre_staload.hats"
#include "share/atspre_staload_libats_ML.hats"

staload UN = "prelude/SATS/unsafe.sats"
staload "libats/libc/SATS/stdio.sats"
staload "libats/libc/SATS/stdlib.sats"
staload "libats/libc/SATS/string.sats"
staload "libats/libc/SATS/unistd.sats"
staload "libats/libc/SATS/errno.sats"
staload "libats/libc/SATS/time.sats"

(* ====================== TYPEDEFS ====================== *)

abstype cerebras_client_type
typedef cerebras_client = cerebras_client_type

abstype http_response_type
typedef http_response = http_response_type

abstype json_builder_type
typedef json_builder = json_builder_type

typedef api_key = string
typedef model_name = string
typedef message_role = string
typedef message_content = string

datatype message = 
  | Message of (message_role, message_content)

datatype chat_request = ChatRequest of {
  model= model_name,
  messages= List0(message),
  temperature= double,
  max_tokens= int,
  stream= bool,
  top_p= double,
  seed= Option(int)
}

datatype chat_response = ChatResponse of {
  id= string,
  model= string,
  content= string,
  finish_reason= string,
  prompt_tokens= int,
  completion_tokens= int,
  total_tokens= int,
  total_time= double
}

datatype api_error = 
  | AuthError of string
  | RateLimitError of string
  | BadRequestError of string
  | NetworkError of string
  | TimeoutError of string
  | ServerError of string
  | ParseError of string

(* ====================== FFI DECLARATIONS ====================== *)

%{^
#include <curl/curl.h>
#include <pthread.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <fcntl.h>
#include <sys/epoll.h>
#include <signal.h>

#define MAX_CLIENTS 10000
#define BUFFER_SIZE 65536
#define MAX_RESPONSE_SIZE 33554432  // 32MB for 65000 tokens
#define CEREBRAS_API_URL ""

typedef struct {
    char* data;
    size_t size;
    size_t capacity;
} response_buffer_t;

typedef struct {
    CURL* curl_handle;
    char* api_key;
    struct curl_slist* headers;
    response_buffer_t* response_buffer;
    long timeout_ms;
} cerebras_client_t;

typedef struct {
    int socket_fd;
    char request_buffer[BUFFER_SIZE];
    size_t request_size;
    char* response_data;
    size_t response_size;
    int keep_alive;
} client_connection_t;

static size_t write_callback(void* contents, size_t size, size_t nmemb, void* userp) {
    size_t realsize = size * nmemb;
    response_buffer_t* mem = (response_buffer_t*)userp;

    if (mem->size + realsize + 1 > mem->capacity) {
        size_t new_capacity = mem->capacity * 2;
        if (new_capacity < mem->size + realsize + 1) {
            new_capacity = mem->size + realsize + 1;
        }
        char* new_data = (char*)realloc(mem->data, new_capacity);
        if (!new_data) {
            fprintf(stderr, "Memory allocation failed\n");
            return 0;
        }
        mem->data = new_data;
        mem->capacity = new_capacity;
    }

    memcpy(&(mem->data[mem->size]), contents, realsize);
    mem->size += realsize;
    mem->data[mem->size] = '\0';

    return realsize;
}

static response_buffer_t* create_response_buffer() {
    response_buffer_t* buf = (response_buffer_t*)malloc(sizeof(response_buffer_t));
    if (!buf) return NULL;

    buf->capacity = 16384;
    buf->data = (char*)malloc(buf->capacity);
    if (!buf->data) {
        free(buf);
        return NULL;
    }
    buf->size = 0;
    buf->data[0] = '\0';

    return buf;
}

static void free_response_buffer(response_buffer_t* buf) {
    if (buf) {
        if (buf->data) free(buf->data);
        free(buf);
    }
}

static void reset_response_buffer(response_buffer_t* buf) {
    if (buf) {
        buf->size = 0;
        if (buf->data) buf->data[0] = '\0';
    }
}

cerebras_client_t* cerebras_client_create(const char* api_key, long timeout_ms) {
    cerebras_client_t* client = (cerebras_client_t*)malloc(sizeof(cerebras_client_t));
    if (!client) return NULL;

    client->curl_handle = curl_easy_init();
    if (!client->curl_handle) {
        free(client);
        return NULL;
    }

    client->api_key = strdup(api_key);
    if (!client->api_key) {
        curl_easy_cleanup(client->curl_handle);
        free(client);
        return NULL;
    }

    client->response_buffer = create_response_buffer();
    if (!client->response_buffer) {
        free(client->api_key);
        curl_easy_cleanup(client->curl_handle);
        free(client);
        return NULL;
    }

    client->timeout_ms = timeout_ms;

    char auth_header[512];
    snprintf(auth_header, sizeof(auth_header), "Authorization: Bearer %s", api_key);

    client->headers = NULL;
    client->headers = curl_slist_append(client->headers, auth_header);
    client->headers = curl_slist_append(client->headers, "Content-Type: application/json");
    client->headers = curl_slist_append(client->headers, "Accept: application/json");

    curl_easy_setopt(client->curl_handle, CURLOPT_HTTPHEADER, client->headers);
    curl_easy_setopt(client->curl_handle, CURLOPT_URL, CEREBRAS_API_URL);
    curl_easy_setopt(client->curl_handle, CURLOPT_WRITEFUNCTION, write_callback);
    curl_easy_setopt(client->curl_handle, CURLOPT_WRITEDATA, (void*)client->response_buffer);
    curl_easy_setopt(client->curl_handle, CURLOPT_USERAGENT, "ATS-Cerebras-Client/1.0");
    curl_easy_setopt(client->curl_handle, CURLOPT_TIMEOUT_MS, timeout_ms);
    curl_easy_setopt(client->curl_handle, CURLOPT_CONNECTTIMEOUT_MS, 10000);
    curl_easy_setopt(client->curl_handle, CURLOPT_FOLLOWLOCATION, 1L);
    curl_easy_setopt(client->curl_handle, CURLOPT_SSL_VERIFYPEER, 1L);
    curl_easy_setopt(client->curl_handle, CURLOPT_SSL_VERIFYHOST, 2L);
    curl_easy_setopt(client->curl_handle, CURLOPT_TCP_NODELAY, 1L);
    curl_easy_setopt(client->curl_handle, CURLOPT_TCP_KEEPALIVE, 1L);

    return client;
}

void cerebras_client_destroy(cerebras_client_t* client) {
    if (!client) return;

    if (client->headers) curl_slist_free_all(client->headers);
    if (client->curl_handle) curl_easy_cleanup(client->curl_handle);
    if (client->api_key) free(client->api_key);
    if (client->response_buffer) free_response_buffer(client->response_buffer);
    free(client);
}

int cerebras_send_request(cerebras_client_t* client, const char* json_payload) {
    if (!client || !json_payload) return -1;

    reset_response_buffer(client->response_buffer);

    curl_easy_setopt(client->curl_handle, CURLOPT_POSTFIELDS, json_payload);

    CURLcode res = curl_easy_perform(client->curl_handle);

    if (res != CURLE_OK) {
        fprintf(stderr, "CURL error: %s\n", curl_easy_strerror(res));
        return -1;
    }

    long http_code = 0;
    curl_easy_getinfo(client->curl_handle, CURLINFO_RESPONSE_CODE, &http_code);

    return (int)http_code;
}

const char* cerebras_get_response(cerebras_client_t* client) {
    if (!client || !client->response_buffer) return NULL;
    return client->response_buffer->data;
}

// Simple JSON parser functions
const char* json_extract_string(const char* json, const char* key) {
    static char buffer[65536];
    char search_key[256];
    snprintf(search_key, sizeof(search_key), "\"%s\":\"", key);

    const char* start = strstr(json, search_key);
    if (!start) return NULL;

    start += strlen(search_key);
    const char* end = strchr(start, '"');
    if (!end) return NULL;

    size_t len = end - start;
    if (len >= sizeof(buffer)) len = sizeof(buffer) - 1;

    strncpy(buffer, start, len);
    buffer[len] = '\0';

    return buffer;
}

int json_extract_int(const char* json, const char* key) {
    char search_key[256];
    snprintf(search_key, sizeof(search_key), "\"%s\":", key);

    const char* start = strstr(json, search_key);
    if (!start) return 0;

    start += strlen(search_key);
    while (*start == ' ' || *start == '\t') start++;

    return atoi(start);
}

double json_extract_double(const char* json, const char* key) {
    char search_key[256];
    snprintf(search_key, sizeof(search_key), "\"%s\":", key);

    const char* start = strstr(json, search_key);
    if (!start) return 0.0;

    start += strlen(search_key);
    while (*start == ' ' || *start == '\t') start++;

    return atof(start);
}

// JSON escaping
void json_escape_string(const char* src, char* dest, size_t dest_size) {
    size_t j = 0;
    for (size_t i = 0; src[i] != '\0' && j < dest_size - 2; i++) {
        switch (src[i]) {
            case '"':  dest[j++] = '\\'; dest[j++] = '"'; break;
            case '\\': dest[j++] = '\\'; dest[j++] = '\\'; break;
            case '\n': dest[j++] = '\\'; dest[j++] = 'n'; break;
            case '\r': dest[j++] = '\\'; dest[j++] = 'r'; break;
            case '\t': dest[j++] = '\\'; dest[j++] = 't'; break;
            default:   dest[j++] = src[i]; break;
        }
    }
    dest[j] = '\0';
}

%}

(* ====================== EXTERNAL FUNCTIONS ====================== *)

extern fun cerebras_client_create (api_key: string, timeout_ms: lint): ptr = "mac#"
extern fun cerebras_client_destroy (client: ptr): void = "mac#"
extern fun cerebras_send_request (client: ptr, json_payload: string): int = "mac#"
extern fun cerebras_get_response (client: ptr): string = "mac#"
extern fun json_extract_string (json: string, key: string): string = "mac#"
extern fun json_extract_int (json: string, key: string): int = "mac#"
extern fun json_extract_double (json: string, key: string): double = "mac#"
extern fun json_escape_string (src: string, dest: &string, dest_size: size_t): void = "mac#"

(* ====================== CLIENT IMPLEMENTATION ====================== *)

implement cerebras_client_make (api_key: string): cerebras_client = let
  val ptr = cerebras_client_create(api_key, 120000L)
in
  $UN.cast{cerebras_client}(ptr)
end

implement cerebras_client_free (client: cerebras_client): void = let
  val ptr = $UN.cast{ptr}(client)
in
  cerebras_client_destroy(ptr)
end

(* ====================== JSON BUILDER ====================== *)

fun build_chat_request_json (
  model: model_name,
  messages: List0(message),
  temperature: double,
  max_tokens: int,
  stream: bool,
  top_p: double,
  seed: Option(int)
): string = let
  fun escape_content (content: string): string = content (* Simple version *)

  fun build_messages (msgs: List0(message)): string = 
    case+ msgs of
    | list_nil() => ""
    | list_cons(Message(role, content), rest) => let
        val escaped = escape_content(content)
        val msg = strptr2string(string_append("{\"role\":\"", string_append(role, string_append("\",\"content\":\"", string_append(escaped, "\"}"))))) 
        val rest_str = build_messages(rest)
      in
        case+ rest of
        | list_nil() => msg
        | list_cons _ => strptr2string(string_append(msg, string_append(",", rest_str)))
      end

  val messages_json = build_messages(messages)
  val stream_str = if stream then "true" else "false"

  val json = case+ seed of
    | None() => strptr2string(
        string_append("{\"model\":\"", string_append(model, string_append(
        "\",\"messages\":[", string_append(messages_json, string_append(
        "],\"temperature\":", string_append(tostring_val<double>(temperature), string_append(
        ",\"max_tokens\":", string_append(tostring_val<int>(max_tokens), string_append(
        ",\"top_p\":", string_append(tostring_val<double>(top_p), string_append(
        ",\"stream\":", string_append(stream_str, "}"))))))))))))
    | Some(s) => strptr2string(
        string_append("{\"model\":\"", string_append(model, string_append(
        "\",\"messages\":[", string_append(messages_json, string_append(
        "],\"temperature\":", string_append(tostring_val<double>(temperature), string_append(
        ",\"max_tokens\":", string_append(tostring_val<int>(max_tokens), string_append(
        ",\"top_p\":", string_append(tostring_val<double>(top_p), string_append(
        ",\"seed\":", string_append(tostring_val<int>(s), string_append(
        ",\"stream\":", string_append(stream_str, "}"))))))))))))
in
  json
end

(* ====================== API FUNCTIONS ====================== *)

fun send_chat_completion (
  client: cerebras_client,
  request: chat_request
): Either(api_error, chat_response) = let
  val ChatRequest(req) = request
  val json_payload = build_chat_request_json(
    req.model,
    req.messages,
    req.temperature,
    req.max_tokens,
    req.stream,
    req.top_p,
    req.seed
  )

  val ptr = $UN.cast{ptr}(client)
  val http_code = cerebras_send_request(ptr, json_payload)

  val response_json = cerebras_get_response(ptr)
in
  case+ http_code of
  | 200 => let
      val content = json_extract_string(response_json, "content")
      val id = json_extract_string(response_json, "id")
      val model = json_extract_string(response_json, "model")
      val finish_reason = json_extract_string(response_json, "finish_reason")
      val prompt_tokens = json_extract_int(response_json, "prompt_tokens")
      val completion_tokens = json_extract_int(response_json, "completion_tokens")
      val total_tokens = json_extract_int(response_json, "total_tokens")
      val total_time = json_extract_double(response_json, "total_time")

      val response = ChatResponse({
        id= id,
        model= model,
        content= content,
        finish_reason= finish_reason,
        prompt_tokens= prompt_tokens,
        completion_tokens= completion_tokens,
        total_tokens= total_tokens,
        total_time= total_time
      })
    in
      Right(response)
    end
  | 401 => Left(AuthError("Invalid API key"))
  | 429 => Left(RateLimitError("Rate limit exceeded"))
  | 400 => Left(BadRequestError("Bad request"))
  | _ => Left(ServerError("Server error: " + tostring_val<int>(http_code)))
end

(* ====================== HTTP SERVER ====================== *)

%{^
static volatile int server_running = 1;

void signal_handler(int signum) {
    server_running = 0;
}

int create_server_socket(int port) {
    int server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        perror("socket creation failed");
        return -1;
    }

    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR | SO_REUSEPORT, &opt, sizeof(opt))) {
        perror("setsockopt failed");
        close(server_fd);
        return -1;
    }

    struct sockaddr_in address;
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(port);

    if (bind(server_fd, (struct sockaddr*)&address, sizeof(address)) < 0) {
        perror("bind failed");
        close(server_fd);
        return -1;
    }

    if (listen(server_fd, MAX_CLIENTS) < 0) {
        perror("listen failed");
        close(server_fd);
        return -1;
    }

    fcntl(server_fd, F_SETFL, O_NONBLOCK);

    return server_fd;
}

void handle_http_request(int client_fd, cerebras_client_t* cerebras_client) {
    char buffer[BUFFER_SIZE];
    ssize_t bytes_read = recv(client_fd, buffer, sizeof(buffer) - 1, 0);

    if (bytes_read <= 0) {
        close(client_fd);
        return;
    }

    buffer[bytes_read] = '\0';

    // Parse HTTP request
    char* body = strstr(buffer, "\r\n\r\n");
    if (!body) {
        const char* error_response = 
            "HTTP/1.1 400 Bad Request\r\n"
            "Content-Type: application/json\r\n"
            "Access-Control-Allow-Origin: *\r\n"
            "Connection: close\r\n\r\n"
            "{\"error\":\"Invalid request\"}";
        send(client_fd, error_response, strlen(error_response), 0);
        close(client_fd);
        return;
    }

    body += 4; // Skip \r\n\r\n

    // Check if it's a POST request to /api/chat
    if (strncmp(buffer, "POST /api/chat", 14) == 0) {
        int http_code = cerebras_send_request(cerebras_client, body);
        const char* response_data = cerebras_get_response(cerebras_client);

        if (http_code == 200 && response_data) {
            char http_response[MAX_RESPONSE_SIZE];
            int len = snprintf(http_response, sizeof(http_response),
                "HTTP/1.1 200 OK\r\n"
                "Content-Type: application/json\r\n"
                "Access-Control-Allow-Origin: *\r\n"
                "Content-Length: %zu\r\n"
                "Connection: keep-alive\r\n\r\n%s",
                strlen(response_data), response_data);

            send(client_fd, http_response, len, 0);
        } else {
            const char* error_response = 
                "HTTP/1.1 500 Internal Server Error\r\n"
                "Content-Type: application/json\r\n"
                "Access-Control-Allow-Origin: *\r\n"
                "Connection: close\r\n\r\n"
                "{\"error\":\"Cerebras API error\"}";
            send(client_fd, error_response, strlen(error_response), 0);
        }
    } else if (strncmp(buffer, "OPTIONS", 7) == 0) {
        // CORS preflight
        const char* cors_response = 
            "HTTP/1.1 204 No Content\r\n"
            "Access-Control-Allow-Origin: *\r\n"
            "Access-Control-Allow-Methods: GET, POST, OPTIONS\r\n"
            "Access-Control-Allow-Headers: Content-Type, Authorization\r\n"
            "Access-Control-Max-Age: 86400\r\n"
            "Connection: keep-alive\r\n\r\n";
        send(client_fd, cors_response, strlen(cors_response), 0);
    } else if (strncmp(buffer, "GET /health", 11) == 0) {
        // Health check endpoint
        const char* health_response = 
            "HTTP/1.1 200 OK\r\n"
            "Content-Type: application/json\r\n"
            "Connection: keep-alive\r\n\r\n"
            "{\"status\":\"healthy\",\"service\":\"cerebras-ats-backend\"}";
        send(client_fd, health_response, strlen(health_response), 0);
    } else {
        const char* not_found = 
            "HTTP/1.1 404 Not Found\r\n"
            "Content-Type: application/json\r\n"
            "Connection: close\r\n\r\n"
            "{\"error\":\"Not found\"}";
        send(client_fd, not_found, strlen(not_found), 0);
    }

    close(client_fd);
}

void run_http_server(int port, cerebras_client_t* cerebras_client) {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int server_fd = create_server_socket(port);
    if (server_fd < 0) {
        fprintf(stderr, "Failed to create server socket\n");
        return;
    }

    printf("ATS Cerebras Backend listening on port %d\n", port);
    printf("Endpoints:\n");
    printf("  POST /api/chat - Chat completion\n");
    printf("  GET  /health   - Health check\n");

    int epoll_fd = epoll_create1(0);
    if (epoll_fd < 0) {
        perror("epoll_create1 failed");
        close(server_fd);
        return;
    }

    struct epoll_event event, events[MAX_CLIENTS];
    event.events = EPOLLIN;
    event.data.fd = server_fd;

    if (epoll_ctl(epoll_fd, EPOLL_CTL_ADD, server_fd, &event) < 0) {
        perror("epoll_ctl failed");
        close(epoll_fd);
        close(server_fd);
        return;
    }

    while (server_running) {
        int nfds = epoll_wait(epoll_fd, events, MAX_CLIENTS, 1000);

        for (int i = 0; i < nfds; i++) {
            if (events[i].data.fd == server_fd) {
                struct sockaddr_in client_addr;
                socklen_t client_len = sizeof(client_addr);
                int client_fd = accept(server_fd, (struct sockaddr*)&client_addr, &client_len);

                if (client_fd >= 0) {
                    handle_http_request(client_fd, cerebras_client);
                }
            }
        }
    }

    close(epoll_fd);
    close(server_fd);
    printf("\nServer stopped gracefully\n");
}

%}

extern fun run_http_server (port: int, client: ptr): void = "mac#"

(* ====================== MAIN IMPLEMENTATION ====================== *)

implement main0 () = {
  val api_key = (
    case+ getenv("CEREBRAS_API_KEY") of
    | ~None_vt() => let
        val () = println! "ERROR: CEREBRAS_API_KEY environment variable not set"
        val () = println! "Usage: export CEREBRAS_API_KEY='your-api-key-here'"
      in
        exit(1)
      end
    | ~Some_vt(key) => strptr2string(key)
  )

  val () = println! "Initializing Cerebras ATS Backend..."
  val () = println! ("API Key loaded: " + string_make_substring(api_key, 0, 10) + "...")

  val client_ptr = cerebras_client_create(api_key, 120000L)
  val () = if iseqz(client_ptr) then (println! "ERROR: Failed to create Cerebras client"; exit(1))

  val () = println! "Client initialized successfully"

  val port = 8080
  val () = run_http_server(port, client_ptr)

  val () = cerebras_client_destroy(client_ptr)
  val () = println! "Cleanup complete"
}
```

Ezután a **Makefile**:

```makefile
# Makefile for ATS Cerebras Backend

ATSCC = patscc
ATSCFLAGS = -O3 -D_GNU_SOURCE -DATS_MEMALLOC_LIBC
LDFLAGS = -lcurl -lpthread -lm

SOURCES = main.dats
TARGET = cerebras_backend

all: $(TARGET)

$(TARGET): $(SOURCES)
	$(ATSCC) $(ATSCFLAGS) -o $@ $^ $(LDFLAGS)

clean:
	rm -f $(TARGET) *_dats.c *_sats.c *.o

run: $(TARGET)
	@echo "Starting Cerebras ATS Backend..."
	@export CEREBRAS_API_KEY="${CEREBRAS_API_KEY}"; ./$(TARGET)

install-deps:
	@echo "Installing dependencies..."
	apt-get update && apt-get install -y libcurl4-openssl-dev build-essential

test: $(TARGET)
	@echo "Testing health endpoint..."
	@./$(TARGET) & 
	@sleep 2
	@curl 
	@pkill -f cerebras_backend

.PHONY: all clean run install-deps test
```

