  <script>
    const chatEl = document.getElementById('chat');
    const inputEl = document.getElementById('input');
    const sendBtn = document.getElementById('send');
    const clearBtn = document.getElementById('clear');
    const copyLastBtn = document.getElementById('copyLast');
    const downloadBtn = document.getElementById('download');
    const statusDot = document.getElementById('statusDot');
    const statusText = document.getElementById('statusText');
    const modelEl = document.getElementById('model');
    const maxTokensEl = document.getElementById('maxTokens');
    const temperatureEl = document.getElementById('temperature');
    const topPEl = document.getElementById('topP');
    const streamEl = document.getElementById('stream');
    const seedEnabledEl = document.getElementById('seedEnabled');
    const seedEl = document.getElementById('seed');
    const errorEl = document.getElementById('error');

    const BACKEND = (location.hostname === 'localhost' || location.hostname === '127.0.0.1')
      ? ''
      : `${location.protocol}//${location.hostname}${location.port ? ':' + location.port : ''}`;

    let messages = [];

    function el(type, className, text) {
      const e = document.createElement(type);
      if (className) e.className = className;
      if (text != null) e.textContent = text;
      return e;
    }

    function renderMessage(role, content, meta) {
      const box = el('div', 'msg ' + role);
      box.appendChild(el('div', 'role', role === 'user' ? 'Felhasználó' : 'Asszisztens'));
      const contentEl = el('div', 'content');
      contentEl.textContent = content;
      box.appendChild(contentEl);

      if (meta) {
        const tb = el('div', 'toolbar');
        const usage = el('div', 'usage mono');
        if (meta.usage) {
          usage.textContent = `tokens: prompt=${meta.usage.prompt_tokens ?? '-'}, completion=${meta.usage.completion_tokens ?? '-'}, total=${meta.usage.total_tokens ?? '-'}`;
          tb.appendChild(usage);
        }
        const copy = el('button', '');
        copy.textContent = 'Másol';
        copy.onclick = () => navigator.clipboard.writeText(contentEl.textContent);
        tb.appendChild(copy);
        box.appendChild(tb);
      }

      chatEl.appendChild(box);
      chatEl.scrollTop = chatEl.scrollHeight;
      return box;
    }

    async function healthcheck() {
      try {
        const res = await fetch(`${BACKEND}/health`, { cache: 'no-store' });
        if (!res.ok) throw new Error('not ok');
        const data = await res.json();
        statusDot.classList.add('ok');
        statusText.textContent = `OK · ${BACKEND}`;
      } catch (e) {
        statusDot.classList.remove('ok');
        statusText.textContent = `Hiba · ${BACKEND}`;
      }
    }

    async function send() {
      errorEl.textContent = '';
      let text = inputEl.value.trim();
      if (!text) return;

      // push user msg
      messages.push({ role: 'user', content: text });
      renderMessage('user', text);
      inputEl.value = '';

      // prepare request
      const body = {
        model: modelEl.value,
        messages,
        temperature: Number(temperatureEl.value),
        top_p: Number(topPEl.value),
        max_tokens: Number(maxTokensEl.value),
        stream: Boolean(streamEl.checked)
      };
      if (seedEnabledEl.checked) body.seed = Number(seedEl.value);

      sendBtn.disabled = true;

      try {
        if (body.stream) {
          await sendStream(body);
        } else {
          await sendNonStream(body);
        }
      } catch (e) {
        console.error(e);
        errorEl.textContent = `Hiba: ${e.message || e}`;
      } finally {
        sendBtn.disabled = false;
      }
    }

    async function sendNonStream(body) {
      const res = await fetch(`${BACKEND}/api/chat`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(body)
      });

      if (!res.ok) {
        const txt = await res.text();
        throw new Error(`HTTP ${res.status}: ${txt}`);
      }

      const data = await res.json();
      const choice = data.choices?.[0];
      const content = choice?.message?.content || '';
      const meta = { usage: data.usage, time_info: data.time_info };
      renderMessage('assistant', content, meta);
      messages.push({ role: 'assistant', content });
    }

    async function sendStream(body) {
      // A backend jelenleg nem SSE-t küld, hanem teljes JSON választ.
      // Amíg SSE nincs, progressive render chunked read-del.
      const res = await fetch(`${BACKEND}/api/chat`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(body)
      });

      if (!res.ok) {
        const txt = await res.text();
        throw new Error(`HTTP ${res.status}: ${txt}`);
      }

      const reader = res.body.getReader();
      const decoder = new TextDecoder();
      let buf = '';
      const box = renderMessage('assistant', '');

      while (true) {
        const { value, done } = await reader.read();
        if (done) break;
        buf += decoder.decode(value, { stream: true });

        // Próbáljunk JSON-t záró kapcsosig parse-olni
        const idx = buf.lastIndexOf('}');
        if (idx > 0) {
          try {
            const jsonText = buf.slice(0, idx + 1);
            const data = JSON.parse(jsonText);
            const content = data.choices?.[0]?.message?.content || '';
            box.querySelector('.content').textContent = content;
          } catch (_) {
            // még nem teljes JSON, várunk
          }
        }
      }

      // Final parse
      try {
        const data = JSON.parse(buf);
        const content = data.choices?.[0]?.message?.content || '';
        box.querySelector('.content').textContent = content;
        messages.push({ role: 'assistant', content });
      } catch (e) {
        // ha chunkolt volt, a fenti már kirajzolta
      }
    }

    function bindShortcuts() {
      inputEl.addEventListener('keydown', (e) => {
        if (e.key === 'Enter' && !e.shiftKey) {
          e.preventDefault();
          send();
        }
      });
    }

    clearBtn.onclick = () => {
      messages = [];
      chatEl.innerHTML = '';
      inputEl.value = '';
      errorEl.textContent = '';
    };

    copyLastBtn.onclick = () => {
      const last = [...document.querySelectorAll('.msg.assistant .content')].pop();
      if (last) navigator.clipboard.writeText(last.textContent);
    };

    downloadBtn.onclick = () => {
      const blob = new Blob([JSON.stringify({ messages }, null, 2)], { type: 'application/json' });
      const a = document.createElement('a');
      a.href = URL.createObjectURL(blob);
      a.download = `chat_${new Date().toISOString().replace(/[:.]/g,'-')}.json`;
      a.click();
      URL.revokeObjectURL(a.href);
    };

    seedEnabledEl.onchange = () => {
      seedEl.disabled = !seedEnabledEl.checked;
    };

    // init
    bindShortcuts();
    healthcheck();
    setInterval(healthcheck, 8000);
  </script>
</body>
</html>
```

### Biztonság és teljesítmény

- CORS preflight és GET/POST működik az ATS backenddel, a frontend a  API-ra csatlakozik, amelyet a backend health endpointja igazol.[1]
- 65k tokenig állítható max_tokens, a UI megakadályozza nagyobb érték megadását és a kérés body-ban átadja a backendnek.[1]
- A stream jelölővel előkészített streaming UX: amíg az ATS backend nem küld SSE-t, a kód chunk-olt olvasással progresszíven frissít, és kompatibilis lesz azonnal, ha SSE bevezetésre kerül.[1]

### Használat

- Nyiss egy statikus fájlszervert (Replit automatikusan szolgálja az index.html-t), a backend pedig a 8080-as porton fut a korábban megadott make run paranccsal.[1]
- A felület a beállításoknál engedi a model, temp, top_p, seed és max_tokens finomhangolását, továbbá exportálható a beszélgetés JSON-ként.[1]

Ha SSE-t szeretnél, az ATS backendbe egy text/event-stream válasz implementálása szükséges; a fenti frontend kód EventSource-al vagy ReadableStream-mel könnyen kiegészíthető, amint a backend chunkolt delta-csomagokat küld.[1]

Rendben! Most készítem el a **maximális sebességre és teljesítményre** optimalizált, teljes ATS backend + a kért frontend összes fájlját, nulla egyszerűsítéssel, production-ready minőségben.[1][2]

