// ==================== CONFIGURATION ====================
#define MAX_WORKERS 16
#define MAX_EVENTS 1024
#define BUFFER_SIZE 131072        // 128KB
#define MAX_RESPONSE_SIZE 67108864 // 64MB for 65K tokens
#define CONNECTION_POOL_SIZE 32
#define CEREBRAS_API_URL ""
#define SERVER_PORT 8080
#define BACKLOG 8192
#define SO_RCVBUF_SIZE 262144
#define SO_SNDBUF_SIZE 262144

// ==================== ATOMIC STATE ====================
static atomic_int server_running = 1;
static atomic_ullong total_requests = 0;
static atomic_ullong total_bytes_sent = 0;
static atomic_ullong total_bytes_recv = 0;

// ==================== MEMORY POOL ====================
typedef struct {
    char* data;
    size_t size;
    size_t capacity;
    atomic_int ref_count;
} buffer_t;

typedef struct {
    buffer_t* buffers[CONNECTION_POOL_SIZE];
    atomic_int indices[CONNECTION_POOL_SIZE];
    pthread_mutex_t lock;
} buffer_pool_t;

static buffer_pool_t* global_buffer_pool = NULL;

buffer_pool_t* buffer_pool_create() {
    buffer_pool_t* pool = aligned_alloc(64, sizeof(buffer_pool_t));
    if (!pool) return NULL;

    pthread_mutex_init(&pool->lock, NULL);

    for (int i = 0; i < CONNECTION_POOL_SIZE; i++) {
        pool->buffers[i] = aligned_alloc(64, sizeof(buffer_t));
        if (!pool->buffers[i]) continue;

        pool->buffers[i]->capacity = MAX_RESPONSE_SIZE;
        pool->buffers[i]->data = aligned_alloc(4096, MAX_RESPONSE_SIZE);
        pool->buffers[i]->size = 0;
        atomic_init(&pool->buffers[i]->ref_count, 0);
        atomic_init(&pool->indices[i], 1);

        if (pool->buffers[i]->data) {
            madvise(pool->buffers[i]->data, MAX_RESPONSE_SIZE, MADV_HUGEPAGE);
        }
    }

    return pool;
}

buffer_t* buffer_pool_acquire(buffer_pool_t* pool) {
    for (int i = 0; i < CONNECTION_POOL_SIZE; i++) {
        int expected = 1;
        if (atomic_compare_exchange_strong(&pool->indices[i], &expected, 0)) {
            buffer_t* buf = pool->buffers[i];
            buf->size = 0;
            atomic_store(&buf->ref_count, 1);
            return buf;
        }
    }

    // Fallback: allocate new
    buffer_t* buf = aligned_alloc(64, sizeof(buffer_t));
    buf->capacity = MAX_RESPONSE_SIZE;
    buf->data = aligned_alloc(4096, MAX_RESPONSE_SIZE);
    buf->size = 0;
    atomic_init(&buf->ref_count, 1);
    madvise(buf->data, MAX_RESPONSE_SIZE, MADV_HUGEPAGE);
    return buf;
}

void buffer_pool_release(buffer_pool_t* pool, buffer_t* buf) {
    int ref = atomic_fetch_sub(&buf->ref_count, 1);
    if (ref <= 1) {
        for (int i = 0; i < CONNECTION_POOL_SIZE; i++) {
            if (pool->buffers[i] == buf) {
                buf->size = 0;
                atomic_store(&pool->indices[i], 1);
                return;
            }
        }
        free(buf->data);
        free(buf);
    }
}

// ==================== CURL CONNECTION POOL ====================
typedef struct {
    CURL* handle;
    struct curl_slist* headers;
    buffer_t* response_buffer;
    atomic_int in_use;
    char error_buffer[CURL_ERROR_SIZE];
} curl_conn_t;

typedef struct {
    curl_conn_t connections[CONNECTION_POOL_SIZE];
    atomic_int initialized;
    char* api_key;
} curl_pool_t;

static curl_pool_t* global_curl_pool = NULL;

static size_t curl_write_callback(void* contents, size_t size, size_t nmemb, void* userp) {
    size_t realsize = size * nmemb;
    buffer_t* buf = (buffer_t*)userp;

    if (buf->size + realsize + 1 > buf->capacity) {
        size_t new_cap = buf->capacity * 2;
        if (new_cap < buf->size + realsize + 1) {
            new_cap = buf->size + realsize + 1;
        }

        char* new_data = aligned_alloc(4096, new_cap);
        if (!new_data) return 0;

        memcpy(new_data, buf->data, buf->size);
        free(buf->data);
        buf->data = new_data;
        buf->capacity = new_cap;
        madvise(buf->data, new_cap, MADV_HUGEPAGE);
    }

    memcpy(&buf->data[buf->size], contents, realsize);
    buf->size += realsize;
    buf->data[buf->size] = '\0';

    return realsize;
}

curl_pool_t* curl_pool_create(const char* api_key) {
    curl_pool_t* pool = aligned_alloc(64, sizeof(curl_pool_t));
    if (!pool) return NULL;

    pool->api_key = strdup(api_key);
    atomic_init(&pool->initialized, 1);

    char auth_header[1024];
    snprintf(auth_header, sizeof(auth_header), "Authorization: Bearer %s", api_key);

    for (int i = 0; i < CONNECTION_POOL_SIZE; i++) {
        curl_conn_t* conn = &pool->connections[i];

        conn->handle = curl_easy_init();
        if (!conn->handle) continue;

        conn->headers = NULL;
        conn->headers = curl_slist_append(conn->headers, auth_header);
        conn->headers = curl_slist_append(conn->headers, "Content-Type: application/json");
        conn->headers = curl_slist_append(conn->headers, "Accept: application/json");
        conn->headers = curl_slist_append(conn->headers, "Connection: keep-alive");

        curl_easy_setopt(conn->handle, CURLOPT_HTTPHEADER, conn->headers);
        curl_easy_setopt(conn->handle, CURLOPT_URL, CEREBRAS_API_URL);
        curl_easy_setopt(conn->handle, CURLOPT_WRITEFUNCTION, curl_write_callback);
        curl_easy_setopt(conn->handle, CURLOPT_USERAGENT, "ATS-Cerebras/2.0");
        curl_easy_setopt(conn->handle, CURLOPT_TIMEOUT_MS, 180000L);
        curl_easy_setopt(conn->handle, CURLOPT_CONNECTTIMEOUT_MS, 5000L);
        curl_easy_setopt(conn->handle, CURLOPT_FOLLOWLOCATION, 1L);
        curl_easy_setopt(conn->handle, CURLOPT_SSL_VERIFYPEER, 1L);
        curl_easy_setopt(conn->handle, CURLOPT_SSL_VERIFYHOST, 2L);
        curl_easy_setopt(conn->handle, CURLOPT_TCP_NODELAY, 1L);
        curl_easy_setopt(conn->handle, CURLOPT_TCP_KEEPALIVE, 1L);
        curl_easy_setopt(conn->handle, CURLOPT_TCP_KEEPIDLE, 120L);
        curl_easy_setopt(conn->handle, CURLOPT_TCP_KEEPINTVL, 60L);
        curl_easy_setopt(conn->handle, CURLOPT_HTTP_VERSION, CURL_HTTP_VERSION_2_0);
        curl_easy_setopt(conn->handle, CURLOPT_PIPEWAIT, 1L);
        curl_easy_setopt(conn->handle, CURLOPT_ERRORBUFFER, conn->error_buffer);

        conn->response_buffer = NULL;
        atomic_init(&conn->in_use, 0);
    }

    return pool;
}

curl_conn_t* curl_pool_acquire(curl_pool_t* pool) {
    for (int i = 0; i < CONNECTION_POOL_SIZE; i++) {
        int expected = 0;
        if (atomic_compare_exchange_strong(&pool->connections[i].in_use, &expected, 1)) {
            return &pool->connections[i];
        }
    }
    return NULL;
}

void curl_pool_release(curl_conn_t* conn) {
    if (conn->response_buffer) {
        buffer_pool_release(global_buffer_pool, conn->response_buffer);
        conn->response_buffer = NULL;
    }
    atomic_store(&conn->in_use, 0);
}

int curl_pool_perform(curl_conn_t* conn, const char* json_payload, buffer_t* response_buf) {
    conn->response_buffer = response_buf;
    response_buf->size = 0;

    curl_easy_setopt(conn->handle, CURLOPT_POSTFIELDS, json_payload);
    curl_easy_setopt(conn->handle, CURLOPT_POSTFIELDSIZE, strlen(json_payload));
    curl_easy_setopt(conn->handle, CURLOPT_WRITEDATA, response_buf);

    CURLcode res = curl_easy_perform(conn->handle);

    if (res != CURLE_OK) {
        fprintf(stderr, "[CURL] Error: %s\n", conn->error_buffer);
        return -1;
    }

    long http_code = 0;
    curl_easy_getinfo(conn->handle, CURLINFO_RESPONSE_CODE, &http_code);

    return (int)http_code;
}

// ==================== FAST JSON PARSING ====================
static inline const char* fast_strstr(const char* haystack, const char* needle, size_t haystack_len) {
    if (!haystack || !needle) return NULL;
    size_t needle_len = strlen(needle);
    if (needle_len > haystack_len) return NULL;

    const char* end = haystack + haystack_len - needle_len;
    for (const char* p = haystack; p <= end; p++) {
        if (*p == *needle && memcmp(p, needle, needle_len) == 0) {
            return p;
        }
    }
    return NULL;
}

void json_extract_content(const char* json, size_t json_len, char* out, size_t out_size) {
    const char* key = "\"content\":\"";
    const char* start = fast_strstr(json, key, json_len);
    if (!start) {
        out[0] = '\0';
        return;
    }

    start += strlen(key);
    const char* end = start;

    while (*end && *end != '"') {
        if (*end == '\\' && *(end + 1)) {
            end += 2;
        } else {
            end++;
        }
    }

    size_t len = end - start;
    if (len >= out_size) len = out_size - 1;

    memcpy(out, start, len);
    out[len] = '\0';
}

// ==================== HTTP RESPONSE BUILDER ====================
static inline size_t build_http_response(char* dest, size_t dest_size, const char* body, size_t body_len, int status_code) {
    const char* status_text = (status_code == 200) ? "OK" : 
                              (status_code == 400) ? "Bad Request" :
                              (status_code == 500) ? "Internal Server Error" : "Error";

    return snprintf(dest, dest_size,
        "HTTP/1.1 %d %s\r\n"
        "Content-Type: application/json; charset=utf-8\r\n"
        "Content-Length: %zu\r\n"
        "Access-Control-Allow-Origin: *\r\n"
        "Access-Control-Allow-Methods: GET, POST, OPTIONS\r\n"
        "Access-Control-Allow-Headers: Content-Type, Authorization\r\n"
        "Connection: keep-alive\r\n"
        "Cache-Control: no-cache, no-store, must-revalidate\r\n"
        "X-Content-Type-Options: nosniff\r\n"
        "X-Frame-Options: DENY\r\n"
        "Server: ATS-Cerebras/2.0\r\n"
        "\r\n%.*s",
        status_code, status_text, body_len, (int)body_len, body);
}

// ==================== HTTP REQUEST HANDLER ====================
typedef struct {
    int client_fd;
    buffer_t* request_buffer;
    buffer_t* response_buffer;
} client_context_t;

void handle_request(client_context_t* ctx) {
    char* req = ctx->request_buffer->data;
    size_t req_len = ctx->request_buffer->size;

    // OPTIONS preflight
    if (req_len >= 7 && memcmp(req, "OPTIONS", 7) == 0) {
        const char* response = 
            "HTTP/1.1 204 No Content\r\n"
            "Access-Control-Allow-Origin: *\r\n"
            "Access-Control-Allow-Methods: GET, POST, OPTIONS\r\n"
            "Access-Control-Allow-Headers: Content-Type, Authorization\r\n"
            "Access-Control-Max-Age: 86400\r\n"
            "Connection: keep-alive\r\n\r\n";
        send(ctx->client_fd, response, strlen(response), MSG_NOSIGNAL);
        return;
    }

    // Health check
    if (req_len >= 11 && memcmp(req, "GET /health", 11) == 0) {
        const char* body = "{\"status\":\"healthy\",\"service\":\"cerebras-ats-backend\"}";
        char response[1024];
        size_t len = build_http_response(response, sizeof(response), body, strlen(body), 200);
        send(ctx->client_fd, response, len, MSG_NOSIGNAL);
        atomic_fetch_add(&total_requests, 1);
        return;
    }

    // POST /api/chat
    if (req_len >= 14 && memcmp(req, "POST /api/chat", 14) == 0) {
        char* body_start = strstr(req, "\r\n\r\n");
        if (!body_start) {
            const char* err = "{\"error\":\"Invalid request\"}";
            char response[1024];
            size_t len = build_http_response(response, sizeof(response), err, strlen(err), 400);
            send(ctx->client_fd, response, len, MSG_NOSIGNAL);
            return;
        }
        body_start += 4;

        curl_conn_t* curl_conn = curl_pool_acquire(global_curl_pool);
        if (!curl_conn) {
            const char* err = "{\"error\":\"Connection pool exhausted\"}";
            char response[1024];
            size_t len = build_http_response(response, sizeof(response), err, strlen(err), 503);
            send(ctx->client_fd, response, len, MSG_NOSIGNAL);
            return;
        }

        buffer_t* api_response = buffer_pool_acquire(global_buffer_pool);
        int http_code = curl_pool_perform(curl_conn, body_start, api_response);

        if (http_code == 200 && api_response->size > 0) {
            char* http_response = aligned_alloc(4096, MAX_RESPONSE_SIZE + 4096);
            size_t response_len = build_http_response(http_response, MAX_RESPONSE_SIZE + 4096, 
                                                      api_response->data, api_response->size, 200);

            ssize_t sent = send(ctx->client_fd, http_response, response_len, MSG_NOSIGNAL);
            if (sent > 0) {
                atomic_fetch_add(&total_bytes_sent, sent);
            }

            free(http_response);
        } else {
            const char* err = "{\"error\":\"API request failed\"}";
            char response[1024];
            size_t len = build_http_response(response, sizeof(response), err, strlen(err), 500);
            send(ctx->client_fd, response, len, MSG_NOSIGNAL);
        }

        buffer_pool_release(global_buffer_pool, api_response);
        curl_pool_release(curl_conn);
        atomic_fetch_add(&total_requests, 1);
        return;
    }

    // 404
    const char* err = "{\"error\":\"Not found\"}";
    char response[1024];
    size_t len = build_http_response(response, sizeof(response), err, strlen(err), 404);
    send(ctx->client_fd, response, len, MSG_NOSIGNAL);
}

// ==================== WORKER THREAD ====================
typedef struct {
    int epoll_fd;
    int thread_id;
    pthread_t thread;
} worker_thread_t;

void* worker_run(void* arg) {
    worker_thread_t* worker = (worker_thread_t*)arg;
    struct epoll_event events[MAX_EVENTS];

    while (atomic_load(&server_running)) {
        int nfds = epoll_wait(worker->epoll_fd, events, MAX_EVENTS, 100);

        for (int i = 0; i < nfds; i++) {
            client_context_t* ctx = (client_context_t*)events[i].data.ptr;

            if (events[i].events & EPOLLIN) {
                ssize_t bytes = recv(ctx->client_fd, 
                                     ctx->request_buffer->data + ctx->request_buffer->size,
                                     ctx->request_buffer->capacity - ctx->request_buffer->size - 1,
                                     MSG_DONTWAIT);

                if (bytes > 0) {
                    ctx->request_buffer->size += bytes;
                    ctx->request_buffer->data[ctx->request_buffer->size] = '\0';
                    atomic_fetch_add(&total_bytes_recv, bytes);

                    if (strstr(ctx->request_buffer->data, "\r\n\r\n")) {
                        handle_request(ctx);

                        epoll_ctl(worker->epoll_fd, EPOLL_CTL_DEL, ctx->client_fd, NULL);
                        close(ctx->client_fd);
                        buffer_pool_release(global_buffer_pool, ctx->request_buffer);
                        buffer_pool_release(global_buffer_pool, ctx->response_buffer);
                        free(ctx);
                    }
                } else if (bytes == 0 || (bytes < 0 && errno != EAGAIN && errno != EWOULDBLOCK)) {
                    epoll_ctl(worker->epoll_fd, EPOLL_CTL_DEL, ctx->client_fd, NULL);
                    close(ctx->client_fd);
                    buffer_pool_release(global_buffer_pool, ctx->request_buffer);
                    buffer_pool_release(global_buffer_pool, ctx->response_buffer);
                    free(ctx);
                }
            }
        }
    }

    return NULL;
}

// ==================== MAIN SERVER ====================
void signal_handler(int signum) {
    atomic_store(&server_running, 0);
}

int create_server_socket(int port) {
    int server_fd = socket(AF_INET, SOCK_STREAM | SOCK_NONBLOCK, 0);
    if (server_fd < 0) {
        perror("socket");
        return -1;
    }

    int opt = 1;
    setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR | SO_REUSEPORT, &opt, sizeof(opt));
    setsockopt(server_fd, SOL_SOCKET, SO_RCVBUF, &(int){SO_RCVBUF_SIZE}, sizeof(int));
    setsockopt(server_fd, SOL_SOCKET, SO_SNDBUF, &(int){SO_SNDBUF_SIZE}, sizeof(int));
    setsockopt(server_fd, IPPROTO_TCP, TCP_NODELAY, &opt, sizeof(opt));
    setsockopt(server_fd, IPPROTO_TCP, TCP_QUICKACK, &opt, sizeof(opt));
    setsockopt(server_fd, IPPROTO_TCP, TCP_FASTOPEN, &(int){5}, sizeof(int));

    struct sockaddr_in addr = {0};
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = INADDR_ANY;
    addr.sin_port = htons(port);

    if (bind(server_fd, (struct sockaddr*)&addr, sizeof(addr)) < 0) {
        perror("bind");
        close(server_fd);
        return -1;
    }

    if (listen(server_fd, BACKLOG) < 0) {
        perror("listen");
        close(server_fd);
        return -1;
    }

    return server_fd;
}

void run_server(const char* api_key, int port, int num_workers) {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);
    signal(SIGPIPE, SIG_IGN);

    curl_global_init(CURL_GLOBAL_ALL);

    global_buffer_pool = buffer_pool_create();
    global_curl_pool = curl_pool_create(api_key);

    int server_fd = create_server_socket(port);
    if (server_fd < 0) {
        fprintf(stderr, "Failed to create server socket\n");
        return;
    }

    printf("╔═══════════════════════════════════════════════════════════╗\n");
    printf("║  ATS CEREBRAS BACKEND - ULTRA HIGH PERFORMANCE MODE       ║\n");
    printf("╠═══════════════════════════════════════════════════════════╣\n");
    printf("║  Port:             %d                                    ║\n", port);
    printf("║  Workers:          %d threads                            ║\n", num_workers);
    printf("║  Connection Pool:  %d connections                        ║\n", CONNECTION_POOL_SIZE);
    printf("║  Max Tokens:       65,000                                 ║\n");
    printf("║  Buffer Size:      %d MB                               ║\n", MAX_RESPONSE_SIZE / 1024 / 1024);
    printf("╠═══════════════════════════════════════════════════════════╣\n");
    printf("║  Endpoints:                                               ║\n");
    printf("║    POST /api/chat  - Chat completions                    ║\n");
    printf("║    GET  /health    - Health check                        ║\n");
    printf("╚═══════════════════════════════════════════════════════════╝\n\n");

    worker_thread_t workers[MAX_WORKERS];
    for (int i = 0; i < num_workers; i++) {
        workers[i].thread_id = i;
        workers[i].epoll_fd = epoll_create1(0);
        pthread_create(&workers[i].thread, NULL, worker_run, &workers[i]);
    }

    int accept_epoll = epoll_create1(0);
    struct epoll_event ev = {0};
    ev.events = EPOLLIN;
    ev.data.fd = server_fd;
    epoll_ctl(accept_epoll, EPOLL_CTL_ADD, server_fd, &ev);

    int worker_idx = 0;
    struct epoll_event events[MAX_EVENTS];

    while (atomic_load(&server_running)) {
        int nfds = epoll_wait(accept_epoll, events, MAX_EVENTS, 100);

        for (int i = 0; i < nfds; i++) {
            if (events[i].data.fd == server_fd) {
                struct sockaddr_in client_addr;
                socklen_t client_len = sizeof(client_addr);

                int client_fd = accept4(server_fd, (struct sockaddr*)&client_addr, &client_len, SOCK_NONBLOCK);
                if (client_fd < 0) continue;

                int opt = 1;
                setsockopt(client_fd, IPPROTO_TCP, TCP_NODELAY, &opt, sizeof(opt));
                setsockopt(client_fd, IPPROTO_TCP, TCP_QUICKACK, &opt, sizeof(opt));

                client_context_t* ctx = aligned_alloc(64, sizeof(client_context_t));
                ctx->client_fd = client_fd;
                ctx->request_buffer = buffer_pool_acquire(global_buffer_pool);
                ctx->response_buffer = buffer_pool_acquire(global_buffer_pool);

                struct epoll_event client_ev = {0};
                client_ev.events = EPOLLIN | EPOLLET;
                client_ev.data.ptr = ctx;

                epoll_ctl(workers[worker_idx].epoll_fd, EPOLL_CTL_ADD, client_fd, &client_ev);
                worker_idx = (worker_idx + 1) % num_workers;
            }
        }
    }

    printf("\n[SHUTDOWN] Stopping workers...\n");
    for (int i = 0; i < num_workers; i++) {
        pthread_join(workers[i].thread, NULL);
        close(workers[i].epoll_fd);
    }

    close(accept_epoll);
    close(server_fd);

    printf("[SHUTDOWN] Statistics:\n");
    printf("  Total requests:  %llu\n", atomic_load(&total_requests));
    printf("  Bytes sent:      %llu\n", atomic_load(&total_bytes_sent));
    printf("  Bytes received:  %llu\n", atomic_load(&total_bytes_recv));

    curl_global_cleanup();
    printf("[SHUTDOWN] Cleanup complete\n");
}

%}

