SOURCES = main.dats
TARGET = cerebras_backend

all: $(TARGET)

$(TARGET): $(SOURCES)
	$(ATSCC) $(ATSCFLAGS) $(CFLAGS) -o $@ $^ $(LDFLAGS)
	strip --strip-unneeded $(TARGET)

clean:
	rm -f $(TARGET) *_dats.c *_sats.c *.o

run: $(TARGET)
