  <script>
    const App = (() => {
      const BACKEND_URL = window.location.hostname === 'localhost' || window.location.hostname === '127.0.0.1'
        ? ''
        : `${window.location.protocol}//${window.location.host}`;

      let messages = [];
      let isGenerating = false;
      let currentController = null;
      let db = null;

      // IndexedDB for persistence
      function initDB() {
        return new Promise((resolve, reject) => {
          const request = indexedDB.open('CerebrasChat', 1);

          request.onerror = () => reject(request.error);
          request.onsuccess = () => {
            db = request.result;
            loadMessagesFromDB();
            resolve(db);
          };

          request.onupgradeneeded = (e) => {
            const db = e.target.result;
            if (!db.objectStoreNames.contains('messages')) {
              db.createObjectStore('messages', { keyPath: 'id', autoIncrement: true });
            }
          };
        });
      }

      function saveMessageToDB(message) {
        if (!db) return;
        const transaction = db.transaction(['messages'], 'readwrite');
        const store = transaction.objectStore('messages');
        store.add({ ...message, timestamp: Date.now() });
      }

      function loadMessagesFromDB() {
        if (!db) return;
        const transaction = db.transaction(['messages'], 'readonly');
        const store = transaction.objectStore('messages');
        const request = store.getAll();

        request.onsuccess = () => {
          const stored = request.result;
          if (stored.length > 0) {
            messages = stored.map(m => ({ role: m.role, content: m.content }));
            renderAllMessages();
          }
        };
      }

      function clearDB() {
        if (!db) return;
        const transaction = db.transaction(['messages'], 'readwrite');
        const store = transaction.objectStore('messages');
        store.clear();
      }

      // Health check
      async function healthCheck() {
        try {
          const res = await fetch(`${BACKEND_URL}/health`, { 
            cache: 'no-store',
            signal: AbortSignal.timeout(3000)
          });

          if (res.ok) {
            document.getElementById('statusDot').classList.add('connected');
            document.getElementById('statusText').textContent = 'Csatlakozva';
          } else {
            throw new Error('unhealthy');
          }
        } catch (e) {
          document.getElementById('statusDot').classList.remove('connected');
          document.getElementById('statusText').textContent = 'Kapcsolat hiba';
        }
      }

      // Message rendering
      function createMessageElement(role, content, meta = null) {
        const div = document.createElement('div');
        div.className = `message ${role}`;

        const icon = role === 'user' ? '👤' : '🤖';
        const roleText = role === 'user' ? 'Felhasználó' : 'Asszisztens';

        let html = `
          <div class="message-header">
            <div class="role">
              <span class="role-icon">${icon}</span>
              <span>${roleText}</span>
            </div>
        `;

        if (meta) {
          html += `<div class="message-meta">`;
          if (meta.time) html += `<span>⏱️ ${meta.time.toFixed(2)}s</span>`;
          html += `</div>`;
        }

        html += `</div><div class="content">${escapeHtml(content)}</div>`;

        if (meta && meta.usage) {
          html += `
            <div class="toolbar">
              <div class="usage">
                <div class="usage-item">📥 ${meta.usage.prompt_tokens || 0}</div>
                <div class="usage-item">📤 ${meta.usage.completion_tokens || 0}</div>
                <div class="usage-item">💾 ${meta.usage.total_tokens || 0}</div>
              </div>
              <button onclick="App.copyMessage(this)">📋 Másol</button>
            </div>
          `;
        }

        div.innerHTML = html;
        return div;
      }

      function renderAllMessages() {
        const container = document.getElementById('messages');
        container.innerHTML = '';
        messages.forEach(m => {
          container.appendChild(createMessageElement(m.role, m.content, m.meta));
        });
        scrollToBottom();
      }

      function appendMessage(role, content, meta = null) {
        const container = document.getElementById('messages');
        const el = createMessageElement(role, content, meta);
        container.appendChild(el);
        scrollToBottom();
        return el;
      }

      function scrollToBottom() {
        const main = document.getElementById('chatContainer');
        requestAnimationFrame(() => {
          main.scrollTop = main.scrollHeight;
        });
      }

      function escapeHtml(text) {
        const div = document.createElement('div');
        div.textContent = text;
        return div.innerHTML;
      }

      // API interaction
      async function sendMessage() {
        const input = document.getElementById('messageInput');
        const text = input.value.trim();
        if (!text || isGenerating) return;

        const userMessage = { role: 'user', content: text };
        messages.push(userMessage);
        appendMessage('user', text);
        saveMessageToDB(userMessage);
        input.value = '';

        isGenerating = true;
        document.getElementById('sendBtn').disabled = true;
        document.getElementById('stopBtn').style.display = 'block';
        document.getElementById('sendBtnText').innerHTML = '<span class="spinner"></span>';

        try {
          const requestBody = {
            model: document.getElementById('model').value,
            messages: messages,
            temperature: parseFloat(document.getElementById('temperature').value),
            top_p: parseFloat(document.getElementById('topP').value),
            max_tokens: parseInt(document.getElementById('maxTokens').value),
            stream: document.getElementById('streamEnabled').checked
          };

          if (document.getElementById('seedEnabled').checked) {
            requestBody.seed = parseInt(document.getElementById('seed').value);
          }

          currentController = new AbortController();
          const startTime = performance.now();

          const res = await fetch(`${BACKEND_URL}/api/chat`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(requestBody),
            signal: currentController.signal
          });

          if (!res.ok) {
            throw new Error(`HTTP ${res.status}: ${await res.text()}`);
          }

          const reader = res.body.getReader();
          const decoder = new TextDecoder();
          let buffer = '';
          let assistantEl = appendMessage('assistant', '');
          let contentEl = assistantEl.querySelector('.content');

          while (true) {
            const { done, value } = await reader.read();
            if (done) break;

            buffer += decoder.decode(value, { stream: true });

            // Progressive rendering
            try {
              const parsed = JSON.parse(buffer);
              const content = parsed.choices?.[0]?.message?.content || '';
              const usage = parsed.usage;
              const time = (performance.now() - startTime) / 1000;

              contentEl.textContent = content;

              if (done || parsed.choices?.[0]?.finish_reason) {
                const assistantMessage = { role: 'assistant', content, meta: { usage, time } };
                messages.push(assistantMessage);
                saveMessageToDB(assistantMessage);

                // Update with full metadata
                assistantEl.replaceWith(createMessageElement('assistant', content, { usage, time }));
              }
            } catch (e) {
              // Incomplete JSON, keep accumulating
            }
          }

        } catch (error) {
          if (error.name !== 'AbortError') {
            showError(error.message);
            console.error('Send error:', error);
          }
        } finally {
          isGenerating = false;
          document.getElementById('sendBtn').disabled = false;
          document.getElementById('stopBtn').style.display = 'none';
          document.getElementById('sendBtnText').textContent = '📤 Küldés';
          currentController = null;
        }
      }

      function stopGeneration() {
        if (currentController) {
          currentController.abort();
        }
      }

      function clearChat() {
        if (!confirm('Biztosan törölni szeretnéd a teljes beszélgetést?')) return;
        messages = [];
        document.getElementById('messages').innerHTML = '';
        clearDB();
      }

      function downloadChat() {
        const blob = new Blob([JSON.stringify({ messages, timestamp: new Date().toISOString() }, null, 2)], 
          { type: 'application/json' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `cerebras-chat-${Date.now()}.json`;
        a.click();
        URL.revokeObjectURL(url);
      }

      function copyMessage(btn) {
        const content = btn.closest('.message').querySelector('.content').textContent;
        navigator.clipboard.writeText(content);
        btn.textContent = '✅ Másolva';
        setTimeout(() => btn.textContent = '📋 Másol', 2000);
      }

      function showError(message) {
        const banner = document.createElement('div');
        banner.className = 'error-banner';
        banner.textContent = `❌ Hiba: ${message}`;
        document.body.appendChild(banner);
        setTimeout(() => banner.remove(), 5000);
      }

      // Keyboard shortcuts
      function setupKeyboardShortcuts() {
        const input = document.getElementById('messageInput');

        input.addEventListener('keydown', (e) => {
          if (e.key === 'Enter' && !e.shiftKey) {
            e.preventDefault();
            sendMessage();
          }
        });

        document.getElementById('seedEnabled').addEventListener('change', (e) => {
          document.getElementById('seed').disabled = !e.target.checked;
        });
      }

      // Initialize
      (async function init() {
        await initDB();
        setupKeyboardShortcuts();
        healthCheck();
        setInterval(healthCheck, 10000);
      })();

      return {
        sendMessage,
        stopGeneration,
        clearChat,
        downloadChat,
        copyMessage
      };
    })();
  </script>
</body>
</html>
